import React, { useState } from 'react';
import { Inplace } from 'primereact/inplace';

export default function Accessibility() {
    const [value, setValue] = useState('');
    
    return (
        <div>
            <label htmlFor="inplace-accessibility">Accessible Inplace</label>
            <Inplace 
                id="inplace-accessibility"
                value={value} 
                onChange={(e) => setValue(e.target.value)}
                aria-label="Accessible Inplace input"
                placeholder="Enter inplace"
            />
        </div>
    );
}